};

struct PerfettoPbMsg {
  // Pointer to a non-aligned pre-reserved var-int slot of
  // PROTOZERO_MESSAGE_LENGTH_FIELD_SIZE bytes. If not NULL,
  // protozero_length_buf_finalize() will write the size of proto-encoded
  // message in the pointed memory region.
  uint8_t* size_field;

  // Current size of the buffer.
  uint32_t size;

  struct PerfettoPbMsgWriter* writer;

  struct PerfettoPbMsg* nested;
  struct PerfettoPbMsg* parent;
};

struct PerfettoPbDecoderIterator {
  struct PerfettoPbDecoder decoder;
  struct PerfettoPbDecoderField field;
};

struct PerfettoProducerInitArgs {
  // Bitwise-or of backends that should be enabled.
  PerfettoBackendTypes backends;

  // [Optional] Tune the size of the shared memory buffer between the current
  // process and the service backend(s). This is a trade-off between memory
  // footprint and the ability to sustain bursts of trace writes (see comments
  // in shared_memory_abi.h).
  // If set, the value must be a multiple of 4KB. The value can be ignored if
  // larger than kMaxShmSize (32MB) or not a multiple of 4KB.
  uint32_t shmem_size_hint_kb;
};

struct PerfettoTeCategory NAME = {
      &perfetto_atomic_false,
      PERFETTO_NULL,
      {
          NAME_STR,
          PERFETTO_I_TE_CAT_DESCRIPTION(__VA_ARGS__),
          PERFETTO_I_TE_CAT_LIST_TAGS(NAME, __VA_ARGS__),
          PERFETTO_I_TE_CAT_NUM_TAGS(__VA_ARGS__),
      },
      0,
  };

struct PerfettoTeHlMacroNameAndType {
  const char* name;
  int32_t type;
};

struct PerfettoDs {
  // Pointer to a (atomic) boolean, which is set to true if there is at
  // least one enabled instance of this data source type.
  PERFETTO_ATOMIC(bool) * enabled;
  struct PerfettoDsImpl* impl;
};

struct PerfettoDsParams {
  // Instance lifecycle callbacks.
  //
  // Can be called from any thread.
  PerfettoDsOnSetupCb on_setup_cb;
  PerfettoDsOnStartCb on_start_cb;
  PerfettoDsOnStopCb on_stop_cb;
  PerfettoDsOnDestroyCb on_destroy_cb;
  PerfettoDsOnFlushCb on_flush_cb;

  // These are called to create/delete custom thread-local instance state, which
  // can be accessed with PerfettoDsTracerImplGetCustomTls().
  //
  // Called from inside a trace point. Trace points inside these will be
  // ignored.
  PerfettoDsOnCreateCustomState on_create_tls_cb;
  PerfettoDsOnDeleteCustomState on_delete_tls_cb;

  // These are called to create/delete custom thread-local instance incremental
  // state. Incremental state may be cleared periodically by the tracing service
  // and can be accessed with PerfettoDsTracerImplGetIncrementalState().
  //
  // Called from inside a trace point. Trace points inside these will be
  // ignored.
  PerfettoDsOnCreateCustomState on_create_incr_cb;
  PerfettoDsOnDeleteCustomState on_delete_incr_cb;

  // Passed to all the callbacks as the `user_arg` param.
  void* user_arg;

  // How to behave when running out of shared memory buffer space.
  enum PerfettoDsBufferExhaustedPolicy buffer_exhausted_policy;

  // When true the data source is expected to ack the stop request through the
  // NotifyDataSourceStopped() IPC.
  bool will_notify_on_stop;
};

struct PerfettoDsTracerIterator {
  struct PerfettoDsImplTracerIterator impl;
};

struct PerfettoDsRootTracePacket {
  struct PerfettoPbMsgWriter writer;
  struct perfetto_protos_TracePacket msg;
};

// A registered category.
struct PerfettoTeCategory {
  PERFETTO_ATOMIC(bool) * enabled;
  struct PerfettoTeCategoryImpl* impl;
  struct PerfettoTeCategoryDescriptor desc;
  uint64_t cat_iid;
};

// A track. Must be registered before it can be used in trace events.
struct PerfettoTeRegisteredTrack {
  struct PerfettoTeRegisteredTrackImpl impl;
};

// Identifies a flow: a link between two events.
struct PerfettoTeFlow {
  uint64_t id;
};

// Iterator for all the active instances (on this thread) of a data source type.
struct PerfettoTeLlIterator {
  struct PerfettoTeLlImplIterator impl;
};

// Used to lazily start, only if required, a nested InternedData submessage for
// a TracePacket `tp`. `incr` is the incremental state ABI pointer received from
// PerfettoTeLlIterator.
struct PerfettoTeLlInternContext {
  struct PerfettoTeLlImplIncr* incr;
  struct perfetto_protos_TracePacket* tp;
  struct perfetto_protos_InternedData interned;
  // true if the nested `interned` submessage has been started, false otherwise.
  bool started;
};

struct PerfettoPbDecoder {
  // Pointer to the beginning of the next field that should be decoded.
  const uint8_t* read_ptr;
  // Pointer to one past the end of the buffer.
  const uint8_t* end_ptr;
};

enum PerfettoPbDecoderStatus {
  // A field has been decoded correctly. There is more data into the buffer,
  // starting from an updated `read_ptr`.
  PERFETTO_PB_DECODER_OK = 0,
  // The last field has been decoded correctly until the end. There is no more
  // data into the buffer.
  PERFETTO_PB_DECODER_DONE = 1,
  // The data starting at `read_ptr` cannot be fully decoded as a protobuf
  // field. `read_ptr` has not been updated.
  PERFETTO_PB_DECODER_ERROR = 2,
};

struct PerfettoPbDecoderDelimitedField {
  const uint8_t* start;
  size_t len;
};

struct PerfettoPbDecoderField {
  // PerfettoPbDecoderStatus
  uint32_t status;
  // PerfettoPbWireType
  uint32_t wire_type;
  // The protobuf field id.
  uint32_t id;
  // The value of this field.
  union {
    // For wire type 2.
    struct PerfettoPbDecoderDelimitedField delimited;
    // For wire type 0 and 1.
    uint64_t integer64;
    // For wire type 5.
    uint32_t integer32;
    // For wire type 1.
    double double_val;
    // For wire type 5.
    float float_val;
  } value;
};

struct PerfettoStreamWriter {
  struct PerfettoStreamWriterImpl* impl;

  // Points to the first byte of the current chunk.
  uint8_t* begin;

  // Points to the first byte after the end of the current chunk (STL-style).
  uint8_t* end;

  // Write pointer: points to the first not-yet-written byte of the current
  // chunk.
  uint8_t* write_ptr;

  // Keeps track of all the bytes written in previous chunks (bytes written in
  // the current chunk are not included here).
  size_t written_previously;
};

#if defined(__linux__) || defined(__native_client__)
typedef pid_t PerfettoThreadId;
#elif defined(__Fuchsia__)
