// Fuzzer stub for: static inline uint64_t PerfettoFnv1a(const void* data, size_t size)
// Goal: exercise both normal (size > 0, non-null data) and degenerate (size == 0, null data) paths.
// Constraints enforced:
//  - If size == 0, pass data == nullptr.
//  - If size > 0, pass a pointer to at least `size` readable bytes.
//  - Keep sizes <= 2048 bytes per performance guidance.
{
  // Generate a random buffer; clamp to <= 2048 bytes to respect perf guidance.
  std::string buf = FUZZ_PARAM_STR();
  size_t cap = buf.size();
  if (cap > 2048u) cap = 2048u;

  // 1) Exercise a random-length hash over the buffer (including possibly 0-length case).
  // Select a length in [0, cap]. Note: FUZZ_PARAM is compile-time; still fine to derive a stable choice.
  size_t len1 = cap ? ((size_t)(*FUZZ_PARAM(unsigned int) % (cap + 1u))) : 0u;
  const void* ptr1 = (len1 == 0u) ? nullptr : (const void*)buf.data();
  // Hash call #1 (may be 0-length with nullptr or a proper slice of buf).
  (void)PerfettoFnv1a(ptr1, len1);

  // 2) Exercise a non-empty path deterministically when possible: full clamped buffer length.
  size_t len2 = cap;  // 0 if original buffer was empty (should not happen per macro, but safe). Otherwise <= 2048.
  const void* ptr2 = (len2 == 0u) ? nullptr : (const void*)buf.data();
  uint64_t h2 = PerfettoFnv1a(ptr2, len2);
  // Property: deterministic for identical inputs.
  FUZZ_ASSERT(h2 == PerfettoFnv1a(ptr2, len2), "PerfettoFnv1a must be deterministic for identical inputs");

  // Validation summary: We ensured pointer validity for size>0 and nullptr when size==0.
  // We also asserted determinism for a repeated call with identical parameters.
}

// Generate a valid protobuf field id within 29 bits (wire type uses low 3 bits)
uint32_t field_id = (uint32_t)(*FUZZ_PARAM(uint32_t) & ((1u << 29) - 1));
// Pick a valid wire type from the enum {0,1,2,5}
uint32_t choices[4] = {PERFETTO_PB_WIRE_TYPE_VARINT, PERFETTO_PB_WIRE_TYPE_FIXED64, PERFETTO_PB_WIRE_TYPE_DELIMITED, PERFETTO_PB_WIRE_TYPE_FIXED32};
uint32_t idx = *FUZZ_PARAM(uint32_t) % 4u;
enum PerfettoPbWireType wire_type = (enum PerfettoPbWireType)choices[idx];
// Invoke target
uint32_t tag = PerfettoPbMakeTag((int32_t)field_id, wire_type);
// Validate tag composition properties
FUZZ_ASSERT(((tag >> 3) == field_id), "tag must encode field_id in high bits");
FUZZ_ASSERT(((tag & 0x7u) == (uint32_t)wire_type), "tag must encode wire_type in low 3 bits");
// Validation: Ensures only valid wire types are used and tag encodes/decodes exactly.

// Prepare a writable buffer large enough for any 64-bit varint (<=10 bytes)
std::string buf(16, '\0');
uint8_t* dst = reinterpret_cast<uint8_t*>(&buf[0]);
// Random 64-bit value to encode
uint64_t value = *FUZZ_PARAM(uint64_t);
// Call target and get the advanced pointer
uint8_t* after = PerfettoPbWriteVarInt(value, dst);
// Basic safety checks: pointer must have advanced between 1 and 10 bytes and stay within buffer
size_t written = static_cast<size_t>(after - dst);
if (written == 0 || written > 10 || written > buf.size()) { FUZZ_BAIL(); }
// Optional property: encoding must be canonical length for 0..max; we only assert bounds here for coverage.
// Validation: Verifies non-null, capacity, and that the returned pointer advances within expected varint bounds.

// Prepare a writable buffer with at least 4 bytes
std::string buf(8, '\0');
uint8_t* p = reinterpret_cast<uint8_t*>(&buf[0]);
uint32_t value = *FUZZ_PARAM(uint32_t);
uint8_t* after = PerfettoPbWriteFixed32(value, p);
size_t written = static_cast<size_t>(after - p);
FUZZ_ASSERT(written == 4, "fixed32 must advance by exactly 4 bytes");
FUZZ_ASSERT(written <= buf.size(), "write must stay within buffer bounds");
// Validation: Ensures non-null buffer and that exactly 4 bytes are written.

// Prepare a writable buffer with at least 8 bytes
std::string buf(16, '\0');
uint8_t* p = reinterpret_cast<uint8_t*>(&buf[0]);
uint64_t value = *FUZZ_PARAM(uint64_t);
uint8_t* after = PerfettoPbWriteFixed64(value, p);
size_t written = static_cast<size_t>(after - p);
FUZZ_ASSERT(written == 8, "fixed64 must advance by exactly 8 bytes");
FUZZ_ASSERT(written <= buf.size(), "write must stay within buffer bounds");
// Validation: Ensures non-null buffer and that exactly 8 bytes are written.

// We build a valid varint-encoded buffer using the writer, then optionally truncate to test failure.
std::string full(16, '\0');
uint8_t* start = reinterpret_cast<uint8_t*>(&full[0]);
uint64_t value = *FUZZ_PARAM(uint64_t);
uint8_t* end_ptr = PerfettoPbWriteVarInt(value, start);
size_t enc_len = static_cast<size_t>(end_ptr - start);
if (enc_len == 0 || enc_len > 10 || enc_len > full.size()) { FUZZ_BAIL(); }
// Choose a truncation length in [0, enc_len]. If < enc_len => expect failure; if == enc_len => expect success.
uint32_t pick = *FUZZ_PARAM(uint32_t);
size_t use_len = (enc_len == 0) ? 0 : (size_t)(pick % (enc_len + 1));
const uint8_t* parse_start = start;
const uint8_t* parse_end = start + use_len;
uint64_t out = 0;
const uint8_t* ret = PerfettoPbParseVarInt(parse_start, parse_end, &out);
if (use_len < enc_len) {
  // Incomplete input must return start and set out_value to 0
  FUZZ_ASSERT(ret == parse_start, "incomplete varint must not advance read_ptr");
  FUZZ_ASSERT(out == 0, "incomplete varint must set out_value to 0");
} else {
  // Complete input must advance to end and decode original value
  FUZZ_ASSERT(ret == parse_end, "complete varint must advance to end");
  FUZZ_ASSERT(out == value, "decoded value must match encoded value");
}
// Validation: Exercises both success and incomplete-path; asserts return semantics and decoded value correctness.

int32_t s = (int32_t)(*FUZZ_PARAM(int32_t));
uint32_t enc = PerfettoPbZigZagEncode32(s);
int32_t dec = PerfettoPbZigZagDecode32(enc);
FUZZ_ASSERT(dec == s, "ZigZag32 decode(encode(x)) must equal x");
// Validation: Roundtrip encode->decode property ensures correct mapping over full 32-bit domain.

int64_t s = (int64_t)(*FUZZ_PARAM(int64_t));
uint64_t enc = PerfettoPbZigZagEncode64(s);
int64_t dec = PerfettoPbZigZagDecode64(enc);
FUZZ_ASSERT(dec == s, "ZigZag64 decode(encode(x)) must equal x");
// Validation: Roundtrip encode->decode property ensures correct mapping over full 64-bit domain.

// Validate by decoding a value we know was produced by the encoder
int32_t s = (int32_t)(*FUZZ_PARAM(int32_t));
uint32_t enc = PerfettoPbZigZagEncode32(s);
int32_t dec = PerfettoPbZigZagDecode32(enc);
FUZZ_ASSERT(dec == s, "decode32(encode32(x)) must equal x");
// Validation: Ensures decoder is inverse of encoder for 32-bit values.

// Validate by decoding a value we know was produced by the encoder
int64_t s = (int64_t)(*FUZZ_PARAM(int64_t));
uint64_t enc = PerfettoPbZigZagEncode64(s);
int64_t dec = PerfettoPbZigZagDecode64(enc);
FUZZ_ASSERT(dec == s, "decode64(encode64(x)) must equal x");
// Validation: Ensures decoder is inverse of encoder for 64-bit values.

double d = *FUZZ_PARAM(double);
uint64_t bits = PerfettoPbDoubleToFixed64(d);
// Reconstruct double via memcpy to verify exact bit-cast
double d2 = 0.0;
static_assert(sizeof(double) == sizeof(uint64_t), "double size must be 8 bytes");
memcpy(&d2, &bits, sizeof(bits));
FUZZ_ASSERT(memcmp(&d, &d2, sizeof(double)) == 0, "bit-cast must be lossless roundtrip");
// Validation: Confirms returned integer matches IEEE-754 bit pattern of input double.

float f = *FUZZ_PARAM(float);
uint32_t bits = PerfettoPbFloatToFixed32(f);
// Reconstruct float via memcpy to verify exact bit-cast
float f2 = 0.0f;
static_assert(sizeof(float) == sizeof(uint32_t), "float size must be 4 bytes");
memcpy(&f2, &bits, sizeof(bits));
FUZZ_ASSERT(memcmp(&f, &f2, sizeof(float)) == 0, "bit-cast must be lossless roundtrip");
// Validation: Confirms returned integer matches IEEE-754 bit pattern of input float.

// Initialize the message with the provided writer. This must be called before
// any append operation on msg.
PerfettoPbMsgInit(msg, writer);

// Track initialization state for downstream stubs.
FUZZ_SET_ATTR_INT(msg, "pb_msg_init", 1);
// Associate this msg with a writer and mark it as ready; future operations will
// require this attribute.
FUZZ_SET_ATTR_PTR(msg, "pb_msg_writer", writer);
FUZZ_SET_ATTR_INT(writer, "writer_ready", 1);

// Clear nested/parent state flags on initialization for safety.
FUZZ_SET_ATTR_INT(msg, "has_open_nested", 0);
